mapper.select:
/* 배송정보 조회 */ SELECT di.del_info_no, di.cust_id, di.sell_products_no, di.recipient_nm, di.delivery_company, di.delivery_request, di.delivery_progress, di.register_date, di.depart_date, di.arrive_date from delivery_information di
di.recipient_nm LIKE CONCAT('%', #{searchValue}, '%')
di.cust_id LIKE CONCAT('%', #{searchValue}, '%')
di.delivery_progress LIKE CONCAT('%', #{searchValue}, '%')
order by di.register_date DESC LIMIT #{pageable.rowPerPage} OFFSET #{pageable.offset};
